const auth = $input.first().json.headers?.authorization || '';
if (!auth.startsWith('Bearer ')) return [{ json: { _error: 'AUTH_MISSING_TOKEN', _status: 401 } }];
const token = auth.slice(7);
try {
  const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64url').toString('utf8'));
  if (!payload.sub) throw new Error('No sub');
  if (payload.exp && Date.now()/1000 > payload.exp) throw new Error('JWT expired');
  if (!payload.tenant_id) throw new Error('No tenant_id');
  const body = $input.first().json.body || {};
  const projectId = (body.project_id || '').trim();
  if (!projectId) return [{ json: { _error: 'VALIDATION_FAILED', _status: 400, _details: 'project_id requerido' } }];
  return [{ json: {
    user_id: payload.sub,
    tenant_id: payload.tenant_id,
    role: payload.role || 'architect',
    project_id: projectId,
    user_message: body.user_message || null,
    request_id: 'req_' + Math.random().toString(36).slice(2, 10)
  }}];
} catch (e) {
  return [{ json: { _error: 'AUTH_INVALID_TOKEN', _status: 401, _details: e.message } }];
}

const project = $input.first()?.json;
const sess = $('Decode JWT + Body').first().json;
if (!project || !project.id) {
  return [{ json: { _error: 'PROJECT_NOT_FOUND', _status: 404, _details: 'project_id no existe o sin acceso por RLS' } }];
}
// Mapeo project_type -> tipos de subvencion candidatos
const typeMap = {
  reforma_integral: ['rehabilitacion','eficiencia_energetica','accesibilidad'],
  redistribucion:   ['rehabilitacion','accesibilidad'],
  cambio_uso:       ['rehabilitacion'],
  adecuacion:       ['rehabilitacion','accesibilidad','eficiencia_energetica'],
  apoyo_tecnico:    ['rehabilitacion','accesibilidad'],
  otro:             ['rehabilitacion','eficiencia_energetica','accesibilidad','obra_nueva']
};
const tiposAplicables = typeMap[project.project_type] || ['rehabilitacion'];
return [{ json: {
  ...sess,
  project: {
    id: project.id,
    name: project.name,
    project_type: project.project_type,
    location_province: project.location_province,
    location_city: project.location_city,
    property_type: project.property_type,
    property_area_m2: project.property_area_m2 ? parseFloat(project.property_area_m2) : null,
    budget_target: project.budget_target ? parseFloat(project.budget_target) : null,
    urgency: project.urgency,
    notes: project.notes,
    edad_edificio: project.edad_edificio
  },
  tipos_aplicables: tiposAplicables
}}];

const ctx = $('Build Context').first().json;
const project = ctx.project;
const grantsRows = $('Load Candidate Grants').all().map(i => i.json).filter(g => g && g.id);
const directivesRows = $input.all().map(i => i.json).filter(d => d && d.directiva);

if (grantsRows.length === 0) {
  return [{ json: {
    _no_grants: true,
    user_id: ctx.user_id,
    tenant_id: ctx.tenant_id,
    project_id: project.id,
    request_id: ctx.request_id
  }}];
}

// Construir lista compacta de subvenciones para el LLM
const grantsList = grantsRows.map(g => ({
  grant_id: g.id,
  nombre: g.nombre,
  organismo: g.organismo,
  ambito: g.ambito,
  comunidad_autonoma: g.comunidad_autonoma,
  tipo: g.tipo,
  importe_maximo_eur: g.importe_maximo ? parseFloat(g.importe_maximo) : null,
  porcentaje_maximo: g.porcentaje_maximo ? parseFloat(g.porcentaje_maximo) : null,
  fecha_cierre: g.fecha_cierre,
  url: g.url_convocatoria,
  requisitos: g.requisitos,
  documentacion_requerida: g.documentacion_requerida,
  compatible_con_otras: g.compatible_con_otras,
  normativa_confidence: g.normativa_confidence ? parseFloat(g.normativa_confidence) : null,
  citation_source: g.citation_source
}));

const directivesText = directivesRows.length
  ? directivesRows.map(d => `- (${d.prioridad}) ${d.directiva}${d.contexto ? ' [' + d.contexto + ']' : ''}`).join('\n')
  : '(sin directivas activas en categoria normativa/presupuesto)';

const systemPrompt = `Eres agent_grants_finder, especialista en subvenciones publicas espanolas para reforma y rehabilitacion residencial.\n\nREGLAS DE ORO:\n- NUNCA inventes una subvencion que no este en la lista que te he dado.\n- Si una subvencion no encaja claramente, NO la incluyas (mejor 3 buenas que 5 dudosas).\n- normativa_confidence < 0.7 -> marca la recomendacion como verificar manualmente con el organismo.\n- El arquitecto firma. Tu propones.\n- DEVUELVE SOLO JSON valido, sin texto fuera del JSON.`;

const userPrompt = `CONTEXTO DEL PROYECTO:\n- Nombre: ${project.name}\n- Tipo de obra: ${project.project_type}\n- Superficie: ${project.property_area_m2 ?? '?'} m2\n- Tipo inmueble: ${project.property_type ?? '?'}\n- Ubicacion: ${project.location_city ?? '?'}, ${project.location_province ?? '?'}\n- Presupuesto estimado: ${project.budget_target ?? '?'} EUR\n- Edad del edificio: ${project.edad_edificio ?? 'desconocida'} anos\n- Notas arquitecto: ${project.notes ? project.notes.slice(0, 500) : '(sin notas)'}\n\nSUBVENCIONES ACTIVAS DISPONIBLES (${grantsList.length}):\n${JSON.stringify(grantsList, null, 2)}\n\nDIRECTIVAS DEL ESTUDIO (categoria normativa/presupuesto):\n${directivesText}\n\nTAREA:\n1. Identifica el TOP 5 de subvenciones aplicables a este proyecto, ordenadas por importe potencial × probabilidad de obtencion.\n2. Para cada subvencion, calcula el AHORRO ESTIMADO en EUR aplicando el porcentaje al presupuesto.\n3. Lista la DOCUMENTACION concreta que el arquitecto debe preparar.\n4. Marca COMPATIBILIDADES: que subvenciones son acumulables entre si.\n5. Senala RIESGOS: plazos cortos (<60 dias), requisitos dificiles, etc.\n\nOUTPUT (JSON estricto, SOLO el JSON):\n{\n  \"recomendaciones\": [\n    {\n      \"grant_id\": \"uuid\",\n      \"nombre\": \"...\",\n      \"organismo\": \"...\",\n      \"ahorro_estimado_eur\": 12500,\n      \"porcentaje_aplicable\": 40,\n      \"fecha_limite_solicitud\": \"YYYY-MM-DD\",\n      \"documentacion_requerida\": [\"...\"],\n      \"compatible_con\": [\"grant_id_x\"],\n      \"riesgos\": [\"...\"],\n      \"probabilidad_aprobacion\": \"alta|media|baja\",\n      \"normativa_confidence\": 0.85,\n      \"citation_source\": \"...\",\n      \"verificar_manualmente\": false\n    }\n  ],\n  \"ahorro_total_acumulable_eur\": 18750,\n  \"siguiente_accion_recomendada\": \"...\",\n  \"alertas_plazo_inminente\": []\n}`;

return [{ json: {
  user_id: ctx.user_id,
  tenant_id: ctx.tenant_id,
  project_id: project.id,
  request_id: ctx.request_id,
  grants_count: grantsList.length,
  llm_payload: {
    model: 'gpt-4o-mini',
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: userPrompt }
    ],
    temperature: 0.2,
    max_tokens: 1500,
    response_format: { type: 'json_object' }
  }
}}];

const llm = $input.first()?.json;
const built = $('Build Prompt').first().json;
const raw = llm?.choices?.[0]?.message?.content || '{}';
let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  return [{ json: { _error: 'LLM_INVALID_JSON', _status: 502, _details: e.message, _raw: raw.slice(0, 500), request_id: built.request_id } }];
}
const usage = llm?.usage || {};
const recomendaciones = Array.isArray(parsed.recomendaciones) ? parsed.recomendaciones : [];
return [{ json: {
  user_id: built.user_id,
  tenant_id: built.tenant_id,
  project_id: built.project_id,
  request_id: built.request_id,
  grants_evaluated: built.grants_count,
  recommendations_count: recomendaciones.length,
  ahorro_total: parsed.ahorro_total_acumulable_eur || 0,
  output: parsed,
  model: llm?.model || 'gpt-4o-mini',
  tokens_in: usage.prompt_tokens || 0,
  tokens_out: usage.completion_tokens || 0
}}];

options.queryReplacement:
={{ [
  $json.project_id,
  JSON.stringify({ project_id: $json.project_id, grants_evaluated: $json.grants_evaluated }),
  JSON.stringify($json.output),
  JSON.stringify({ request_id: $json.request_id, model: $json.model, tokens_in: $json.tokens_in, tokens_out: $json.tokens_out, recommendations_count: $json.recommendations_count, ahorro_total_eur: $json.ahorro_total, eu_ai_act: 'asistencia profesional supervisada por tecnico colegiado' })
] }}

